"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Selezioni tutte le facce che devono scomparire (per una tasca pareti e fondo, per un foro la parete, per un raccordo la superficie arrotondata). Le facce adiacenti vengono prolungate sopra la lacuna. Il passo viene ricalcolato alla modifica del corpo; la prima volta viene caricato a tal fine il kernel geometrico completo (alcuni secondi).",
