"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Scorciatoie personalizzate: aprire il menu del gruppo (▾) nella barra degli strumenti, fare clic su ⋮ accanto al comando → «Modifica scorciatoia da tastiera …».",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Quote e note personalizzate si possono trascinare con il mouse sul foglio (distanza della linea di quota, angolo della linea di richiamo, raggio dell'arco dell'angolo). Clic su due angoli = quota di lunghezza. Clic sul bordo di un cerchio nella vista dall'alto = diametro (o raggio). Angolo: prima il vertice, poi un punto su ciascun lato. Smusso: entrambe le estremità dello spigolo inclinato; dà ad es. 2×45°. Il campo di testo dopo ogni quota contiene un'aggiunta come ±0,1, H7 o 4×.",
