"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Una fresa tonda lascia il proprio raggio in ogni angolo interno: un pezzo complementare a spigolo vivo non vi si inserisce. Lo scarico entra brevemente nell'angolo e torna indietro a ogni angolo interno vivo.{0}{1}",
