"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Il loft richiede due schizzi con profili chiusi su piani diversi.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Il loft richiede due schizzi con una curva ciascuno (su piani diversi).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Loft non possibile – controllare le sezioni (un profilo chiuso ciascuna, non ritorto)",
