"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Faccia clic prima sulla faccia del corpo da spostare, poi sulla faccia di destinazione dell'altro corpo. Il corpo viene ruotato e spostato finché il primo punto di clic coincide con il secondo e le facce sono appoggiate l'una sull'altra.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Faccia clic prima sullo spigolo del corpo da spostare, poi sullo spigolo di destinazione dell'altro corpo. Gli spigoli rettilinei vengono resi coincidenti (centro su centro); per gli spigoli circolari – foro e perno – gli assi vengono allineati e i centri portati a coincidere.",
