"Flächen am Körper":"Facce del corpo",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Facce piane all'estremità del pezzo (due piani, quadro, esagono) con una fresa a codolo motorizzata lungo Z. Apertura chiave = doppio della distanza della faccia dall'asse di rotazione. X e C si muovono insieme (interpolazione polare, Fanuc G12.1); senza questo modello nel postprocessore vengono emessi brevi passi X/C.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Cliccare le facce a cui dare spessore (un nuovo clic le rimuove).",
