"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"Nell'immagine speculare l'utensile gira al contrario: la fresatura concordante diventa discordante. Anche la correzione del raggio del controllo cambia lato.",
