"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"I corpi importati non hanno cronologia di progettazione, ma possono essere ulteriormente modificati (raccordo, smusso, taglio …) e usati per il CAM. Con «Asse Y verso l'alto» i modelli provenienti da programmi con Y verso l'alto vengono orientati correttamente.",
