"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"La prima curva di ogni schizzo – aperta o chiusa. Le curve vengono unite da una pelle (superficie senza spessore).",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Ogni asse singolarmente: fare clic su uno spigolo, un angolo, una faccia o un foro. Gli assi non impostati derivano dal punto del grezzo.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Ogni operazione come sottoprogramma (LBL) a fine programma, chiamata con CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Ogni cerchio dello schizzo è il centro di un foro. La foratura avviene in direzione opposta alla normale dello schizzo (nel materiale).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Ogni cerchio dello schizzo viene ripetuto ruotandolo attorno al centro (in coordinate dello schizzo): un cerchio alla distanza del raggio primitivo produce una circonferenza di fori.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Ogni cerchio dello schizzo diventa una griglia: distanze in X e Y dello schizzo (anche negative).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Ora un punto sul secondo lato.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Ora ogni direzione una volta fino a fondo corsa: spostare, tirare, premere, inclinare, ruotare (10 s) …",
