"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Rilasciare il cappuccio e scegliere «Calibra punto zero». Poi provare ogni direzione: la barra deve muoversi e, a riposo, restare nella zona morta grigia.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Spostare il cappuccio = pan, premere/tirare = zoom, inclinare e ruotare = ruotare il modello. Negli schizzi solo pan e zoom. SpaceMouse Pro/Enterprise: T, F, R = vista dall'alto, frontale, destra. Se non succede nulla: chiudere brevemente il driver 3Dconnexion e ricollegare.",
