"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Contorno con {0} punti – Okuma: G85 (LAP) con contorno G81…G80, Fanuc: G71 P…Q…. Il controllo sgrossa con la propria suddivisione delle passate; la simulazione mostrata qui è quella di WerkFab.",
"Kontur zum Freifräsen davor anlegen":"Creare prima un contorno di svuotamento",
"Konturauswahl":"Selezione contorni",
"Konturen außen und innen":"Contorni esterni e interni",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"I contorni seguono il bordo delle aree scure. La linea mediana corre al centro dei tratti – adatta a incisioni e disegni al tratto. «Rette, archi e cerchi» riconosce spigoli rettilinei, angoli vivi, arrotondamenti e cerchi; «Polilinee» segue l'immagine punto per punto. Se necessario, adatti poi la scala con «Calibra modello» o «Scala».",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"I contorni con correzione raggio nel controllo (RL/RR) vengono avvicinati e abbandonati con APPR/DEP; il controllo calcola da sé punto ausiliario e correzione",
