"Kurven":"Curve",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Curve di uno schizzo sulla faccia frontale (trasversale all'asse di rotazione) con una fresa motorizzata lungo Z (X e C si muovono insieme; Fanuc: interpolazione polare G12.1). Le curve aperte vengono fresate andata e ritorno. Profondità dalla faccia frontale.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Le curve di uno schizzo disposto lungo l'asse di rotazione vengono avvolte sulla circonferenza e fresate con una fresa motorizzata rivolta verso l'asse (Z e C si muovono insieme; Fanuc: interpolazione cilindrica G7.1). Il piano dello schizzo determina l'angolo in cui si trova il contorno; i tratti orizzontali dello schizzo diventano archi attorno al pezzo. Profondità dal diametro esterno.",
"Kurzbefehl":"Scorciatoia",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"I percorsi brevi (fino alla distanza di mantenimento) vengono eseguiti in basso con l'avanzamento di transizione invece di passare per la quota di ritiro: senza controllo collisioni, quindi tenerla piccola.",
