"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"Scegliere il materiale nel setup sotto «Grezzo → Materiale del grezzo». La densità determina il peso del grezzo, Vc è un valore indicativo per il metallo duro; il colore viene mostrato nella simulazione.",
