"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Più spigoli consecutivi contano come un unico percorso: il raggio varia dall'inizio della catena alla sua fine, i punti di controllo sono in % della lunghezza totale della catena. Lo calcola il kernel geometrico completo.",
