"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Con i punti di controllo il raggio passa per i valori indicati (posizione in % della lunghezza dello spigolo). Lo calcola il kernel geometrico completo; la prima volta il caricamento richiede alcuni secondi.",
"Mit dem 3D-Taster kann nicht zerspant werden":"Con la sonda 3D non si può lavorare per asportazione",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Confronta con il pezzo finito: verde = a misura, blu = materiale residuo, rosso = troppo profondo",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Portare il mouse accanto a un contorno (il lato determina la direzione) · Esc termina",
"Mit diesem Werkzeug kann nicht gefräst werden":"Con questo utensile non si può fresare",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Con un maschio usare solo il ciclo «Maschiatura» – un ciclo di foratura lo spezzerebbe",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Con più passate la profondità della filettatura viene fresata a gradini che asportano ciascuno circa la stessa quantità: ciò protegge le piccole frese per filettare e i materiali duri. La passata a vuoto ripercorre l'ultimo percorso senza ulteriore passata.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Con «Cicli di foratura» nel programma NC vengono emessi cicli del controllo (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), altrimenti movimenti espansi.",
