"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Solo i profili esterni (perni) sono possibili come ciclo del controllo",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Solo diametro (forma come questo utensile)",
"Nur Innenkonturen (Öffnungen)":"Solo contorni interni (aperture)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Solo le tasche rettangolari e circolari sono possibili come ciclo del controllo",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Lavorare solo ciò che una fresa più grande ha lasciato negli angoli.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Ripassare solo i punti del contorno che una fresa più grande non ha raggiunto (angoli interni, zone strette). Senza archi di attacco/uscita, ponticelli e passate di finitura; compensazione nel computer.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Solo dove l'utensile di riferimento non è arrivato: zone piane in parallelo, zone ripide come linee di livello. Con un utensile dell'elenco conta anche la sua forma, ad esempio ciò che una fresa toroidale lascia nei raccordi.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Solo le facce piane possono fungere da piano di schizzo.",
"Nur ebene Flächen können extrudiert werden":"Solo le facce piane possono essere estruse",
"Nur ebene Flächen lassen sich ersetzen":"Solo le facce piane possono essere sostituite",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Solo le facce piane e cilindriche (fori, perni) possono essere spostate",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Solo facce piane rivolte verso l'alto, verso l'utensile (orizzontali in questo setup).",
"Nur für Außen-Drehmeißel":"Solo per utensili da tornitura esterni",
"Nur in Operationen verwendete":"Solo quelli usati in operazioni",
