"Nut liegt nicht am Teil":"La cava non è sul pezzo",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Cava lungo l'asse di rotazione (ad es. cava per linguetta) con una fresa motorizzata rivolta verso l'asse; il mandrino principale trattiene il pezzo come asse C. Larghezza cava = Ø fresa. Inizio/fine Z in Z del modello; se la cava arriva fino alla faccia frontale, la fresa entra da davanti, altrimenti affonda all'inizio. Profondità dal diametro esterno.",
