"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Gli spigoli aperti sono mostrati in rosso. «Ripara» chiude i buchi.",
"Offene Linie in einer Skizze wählen":"Scegliere una linea aperta in uno schizzo",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Le curve aperte o chiuse vengono estruse perpendicolarmente allo schizzo – il risultato è una superficie (parete senza spessore). Con «Ispessisci» o «Cuci» diventa un volume.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Le curve aperte o chiuse vengono ruotate attorno all'asse – il risultato è una superficie, non un volume.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Senza un tasto personalizzato vale l'impostazione predefinita «{0}».",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Senza «Modellata» la filettatura viene solo rappresentata (veloce). Se modellata, la forma del filetto viene realmente asportata, ad es. per la stampa 3D. Foro per M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP tornitura",
"Okuma OSP-M Fräsen":"Okuma OSP-M fresatura",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 non si portano lì sulle coordinate macchina (G53 annulla la correzione lunghezza utensile) – ritiro all'altezza di sicurezza, nessuna corsa di riferimento XY emessa",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: nessuna funzione di smussatura emessa (G5.1 è Fanuc) – impostare Hi-Cut/Super-NURBS sulla macchina",
