"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: tutte le funzioni. Kernel Rust (truck, sperimentale): primitive, estrusione, rivoluzione, foro, serie, specchia, sposta, scala, combina ed esportazione STEP; le altre feature sono contrassegnate come «non ancora supportate».",
