"Schruppt die Bohrung von der Vorbohrung nach außen (0,2 mm Schlichtaufmaß) und schlichtet sie dann bis zum Grund. Die Bohrstange muss in die Vorbohrung passen.":"Sgrossa il foro dal preforo verso l'esterno (0,2 mm di sovrametallo di finitura) e poi lo finisce fino al fondo. La barra di alesatura deve entrare nel preforo.",
"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"Sgrossa in 4 assi simultanei dall'esterno verso l'interno: una spirale attorno all'asse A per ogni passata (alternando +X e −X), mai più in profondità del pezzo più il sovrametallo. Con fresa a codolo o sferica.",
