"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Tasca nella faccia frontale dai contorni chiusi di uno schizzo (i contorni interni restano come isole), con una fresa a codolo motorizzata lungo Z. Lo svuotamento procede dall'interno verso l'esterno; la fresa entra in rampa lungo il percorso più interno e resta in basso entro un livello. X e C si muovono insieme (Fanuc: interpolazione polare G12.1). Profondità dalla faccia frontale.",
