"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Avvolge le curve dello schizzo sul cilindro: X resta X, la distanza trasversale all'asse diventa un arco sul Ø di sviluppo (rotazione A). Lo schizzo deve essere parallelo all'asse A, ad es. su un piano tangente. Si fresa a profondità fissa sotto la superficie del pezzo: per incisioni, scritte e cave attorno al pezzo.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Come il contorno 3D, ma l'utensile scende in modo continuo senza gradini: nessun segno di affondamento sulle pareti ripide.",
