"{0}: Fläche oder Kante im Modell anklicken.":"{0}: fare clic su una faccia o uno spigolo del modello.",
"{0}: GRBL kennt keine Radiuskorrektur (G41/G42) – Bahn ohne Korrektur ausgegeben":"{0}: GRBL non supporta la compensazione del raggio (G41/G42) – percorso emesso senza compensazione",
"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: l'origine pezzo Y/Z non si trova sull'asse di rotazione A (asse a Y{1} Z{2}) – per il 4 assi simultaneo posizionare l'origine pezzo sull'asse (punto del grezzo centro Y/Z)",
"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0}: postprocessore senza ciclo di tornitura – emesso come percorso",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0}: postprocessore senza interpolazione polare – facce emesse come brevi passi X/C (C in gradi); a seconda del controllo l'avanzamento non vale quindi lungo il percorso. Meglio compilare il modello «Interpolazione polare on/off»",
"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: postprocessore senza modello «Asse C e utensile motorizzato attivi» – attivare a mano asse C e mandrino utensile",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: postprocessore senza interpolazione cilindrica – Z e C si muovono insieme; a seconda del controllo l'avanzamento non vale quindi lungo il percorso. Meglio compilare il modello «Interpolazione cilindrica on/off»",
