"{0}: Schlichtzyklus fährt die Fertigkontur – Aufmaß {1} mm wird nicht berücksichtigt":"{0}: il ciclo di finitura percorre il contorno finito – il sovrametallo di {1} mm non viene considerato",
"{0}: Schlichtzyklus nicht möglich ({1}) – als Bahn ausgegeben":"{0}: ciclo di finitura non possibile ({1}) – emesso come percorso",
